print(f"Total specimens parsed: {len(all_raw_rows)}")

# Field definition
fields = [
    "specimen_id", "total_length", "teslon_ts", "cephalothorax_ct", "carapace_length_cl",
    "carapace_ca", "carapace_cp", "mesosoma_ml", "mt1", "mt1_b", "mt1_h",
    "mt2", "mt2_b", "mt2_h", "mt3", "mt3_b", "mt3_h", "mt4", "mt4_b", "mt4_h",
    "mt5", "mt5_b", "mt5_h", "pedipalp_pp", "femur_fm", "patella_pl", "mannus_mn",
    "fixed_finger_ff", "movable_finger_mf", "pectin_length_pc", "pectin_count_l",
    "pectin_count_r", "pectin_teeth_length_pt", "image_ref", "morpho_by",
    "new_body_length", "new_pectin_count_l", "new_pectin_count_r", "notes"
]

records = []
for r in all_raw_rows:
    rec = {}
    for idx, f in enumerate(fields):
        rec[f] = r[idx]
    
    # Infer Taxonomy and Geography
    sid = rec["specimen_id"].strip()
    
    # Taxon prefix inference:
    # HoSp = Hottentotta sp. (or Heterometrus depending on sub-group, commonly Hottentotta / Hormurus / Hottentotta tamulus in Indian morphometrics)
    # HoTa = Hottentotta tamulus
    # HoPa = Hottentotta pachyurus / Heterometrus pachyurus
    # BuSp = Buthoscorpio sp.
    # LySp = Lychas sp.
    # Gigantometrus = Gigantometrus (Giant black scorpion)
    # Isometrus = Isometrus
    # Bikaner / SAM = Desert Buthids / Hottentotta / Compsobuthus
    
    taxon_group = "Hottentotta sp."
    if "Gigantometrus" in sid:
        taxon_group = "Gigantometrus"
    elif sid.startswith("BuSp") or "Bikaner" in sid or "SAM" in sid:
        taxon_group = "Buthoscorpio / Buthidae"
    elif sid.startswith("HoPa"):
        taxon_group = "Hottentotta / Hormurus (HoPa)"
    elif sid.startswith("HoTa"):
        taxon_group = "Hottentotta tamulus"
    elif sid.startswith("LySp"):
        taxon_group = "Lychas sp."
    elif sid.startswith("Isometrus"):
        taxon_group = "Isometrus sp."
    elif sid.startswith("HoSp"):
        taxon_group = "Hottentotta sp."

    # Region / State inference from code
    # MP: Madhya Pradesh
    # KA: Karnataka
    # MH: Maharashtra
    # TN: Tamil Nadu
    # RJ: Rajasthan
    # GJ: Gujarat
    # OD: Odisha
    # GA: Goa
    # UP: Uttar Pradesh
    # A: Andhra Pradesh / Assam / Area
    region = "Unknown"
    for code, reg_name in [
        ("KA", "Karnataka"),
        ("MP", "Madhya Pradesh"),
        ("MH", "Maharashtra"),
        ("TN", "Tamil Nadu"),
        ("RJ", "Rajasthan"),
        ("GJ", "Gujarat"),
        ("OD", "Odisha"),
        ("GA", "Goa"),
        ("UP", "Uttar Pradesh"),
        ("Savandurga", "Karnataka"),
        ("Wilson's point", "Maharashtra"),
        ("mahabaleshwar", "Maharashtra"),
        ("Bikaner", "Rajasthan"),
        ("SAM", "Rajasthan"),
        ("A", "Andhra / Field-A")
    ]:
        if code in sid:
            region = reg_name
            break

    rec["genus_taxon"] = taxon_group
    rec["region_state"] = region
    
    # Calculate Morphometric Indices & Allometry
    # Metasoma total length sum (mt1 + mt2 + mt3 + mt4 + mt5)
    mts = [rec["mt1"], rec["mt2"], rec["mt3"], rec["mt4"], rec["mt5"]]
    if all(m is not None for m in mts):
        rec["metasoma_total_length"] = round(sum(mts), 2)
    else:
        rec["metasoma_total_length"] = None

    # Pectin Count average & Asymmetry
    pcl = rec["pectin_count_l"]
    pcr = rec["pectin_count_r"]
    if pcl is not None and pcr is not None:
        rec["pectin_count_mean"] = round((pcl + pcr) / 2.0, 1)
        rec["pectin_asymmetry"] = abs(pcl - pcr)
    elif pcl is not None:
        rec["pectin_count_mean"] = float(pcl)
        rec["pectin_asymmetry"] = 0
    elif pcr is not None:
        rec["pectin_count_mean"] = float(pcr)
        rec["pectin_asymmetry"] = 0
    else:
        rec["pectin_count_mean"] = None
        rec["pectin_asymmetry"] = None

    # Chela Finger-to-Manus ratio: mf / mn
    if rec["movable_finger_mf"] and rec["mannus_mn"] and rec["mannus_mn"] > 0:
        rec["finger_to_manus_ratio"] = round(rec["movable_finger_mf"] / rec["mannus_mn"], 3)
    else:
        rec["finger_to_manus_ratio"] = None

    # Metasomal segment 5 elongation: mt5 / mt5_b
    if rec["mt5"] and rec["mt5_b"] and rec["mt5_b"] > 0:
        rec["mt5_elongation_ratio"] = round(rec["mt5"] / rec["mt5_b"], 3)
    else:
        rec["mt5_elongation_ratio"] = None

    # Carapace Aspect: cl / CA (length vs anterior/width)
    if rec["carapace_length_cl"] and rec["carapace_ca"] and rec["carapace_ca"] > 0:
        rec["carapace_aspect_ratio"] = round(rec["carapace_length_cl"] / rec["carapace_ca"], 3)
    else:
        rec["carapace_aspect_ratio"] = None

    # Total Body Length vs Cephalothorax + Mesosoma + Metasoma + Telson
    calc_sum = 0
    parts_valid = True
    for part in ["cephalothorax_ct", "mesosoma_ml", "teslon_ts"]:
        if rec[part] is not None:
            calc_sum += rec[part]
        else:
            parts_valid = False
    if rec["metasoma_total_length"] is not None and parts_valid:
        calc_sum += rec["metasoma_total_length"]
        rec["calculated_total_length"] = round(calc_sum, 2)
        if rec["total_length"]:
            rec["length_diff_pct"] = round(abs(rec["total_length"] - calc_sum) / rec["total_length"] * 100, 2)
        else:
            rec["length_diff_pct"] = None
    else:
        rec["calculated_total_length"] = None
        rec["length_diff_pct"] = None

    # Size class
    tl = rec["total_length"]
    if tl is not None:
        if tl >= 100:
            rec["size_class"] = "Gigantic (≥100mm)"
        elif tl >= 70:
            rec["size_class"] = "Large (70-99mm)"
        elif tl >= 45:
            rec["size_class"] = "Medium (45-69mm)"
        elif tl >= 25:
            rec["size_class"] = "Small (25-44mm)"
        else:
            rec["size_class"] = "Pygmy / Juvenile (<25mm)"
    else:
        rec["size_class"] = "Undetermined"

    records.append(rec)

# Export to JSON
with open("/Users/sreyabondada/Downloads/Parth's workspace/Parth morphometrics/scorpions_morphometrics.json", "w") as f:
    json.dump(records, f, indent=2)

# Export to CSV
all_keys = list(records[0].keys())
with open("/Users/sreyabondada/Downloads/Parth's workspace/Parth morphometrics/scorpions_morphometrics.csv", "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=all_keys)
    writer.writeheader()
    for r in records:
        writer.writerow(r)

print(f"Successfully exported {len(records)} specimens to JSON & CSV!")

# Run summary statistics for analysis
numeric_fields = [f for f in fields if f not in ["specimen_id", "image_ref", "morpho_by", "notes"]]
stats = {}
for nf in numeric_fields:
    vals = [r[nf] for r in records if r[nf] is not None and isinstance(r[nf], (int, float))]
    if vals:
        stats[nf] = {
            "count": len(vals),
            "min": min(vals),
            "max": max(vals),
            "mean": round(sum(vals)/len(vals), 3),
            "median": round(sorted(vals)[len(vals)//2], 3)
        }

print("Summary Stats for Key Variables:")
for k in ["total_length", "teslon_ts", "pedipalp_pp", "pectin_count_l", "pectin_count_r"]:
    print(f"  {k}: {stats.get(k)}")

# Regional breakdown
reg_counts = {}
for r in records:
    rg = r["region_state"]
    reg_counts[rg] = reg_counts.get(rg, 0) + 1
print("\nRegional Distribution:")
print(reg_counts)

# Taxon breakdown
tax_counts = {}
for r in records:
    tx = r["genus_taxon"]
    tax_counts[tx] = tax_counts.get(tx, 0) + 1
print("\nTaxon Distribution:")
print(tax_counts)
